/** @jsxImportSource preact */
import { useEffect, useRef } from "preact/hooks";
import { mountFoldedEmojiScroll, type FoldedEmojiScrollOptions } from "../../components/folded-emoji-scroll/FoldedEmojiScrollEngine.js";
import type { MotionController } from "../../components/folded-emoji-scroll/motion-runtime";

export function FoldedEmojiScroll({ options, className }: { options?: FoldedEmojiScrollOptions; className?: string }) {
  const host = useRef<HTMLDivElement>(null);
  const controller = useRef<MotionController | null>(null);
  useEffect(() => {
    const instance = mountFoldedEmojiScroll(host.current!, options);
    controller.current = instance;
    return () => { instance.destroy(); controller.current = null; };
    // Options are updated below without remounting the state machine.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  useEffect(() => { controller.current?.update(options ?? {}); }, [options]);
  return <div ref={host} className={className} data-motion-component="folded-emoji-scroll" />;
}

